def best_rational(num: int, den: int, max_den: int, side: int = 0) -> tuple[int, int]:
    if den == 0 or max_den < 1 or side not in (-1, 0, 1):
        raise ValueError

    def gcd(a: int, b: int) -> int:
        a = abs(a)
        b = abs(b)
        while b:
            a, b = b, a % b
        return a

    def reduce_frac(p: int, q: int) -> tuple[int, int]:
        if q == 0:
            raise ValueError
        if q < 0:
            p, q = -p, -q
        if p == 0:
            return (0, 1)
        g = gcd(p, q)
        return (p // g, q // g)

    g = gcd(num, den)
    n = num // g
    d = den // g
    if d < 0:
        n, d = -n, -d

    if d <= max_den:
        return (n, d)

    # Continued fraction of n/d with all partial quotients after the first positive.
    cf = []
    a, b = n, d
    while b != 0:
        q = a // b
        r = a % b
        cf.append(q)
        a, b = b, r

    cp = []
    cq = []

    p_m2, p_m1 = 0, 1
    q_m2, q_m1 = 1, 0

    for ai in cf:
        p = ai * p_m1 + p_m2
        q = ai * q_m1 + q_m2
        cp.append(p)
        cq.append(q)
        p_m2, p_m1 = p_m1, p
        q_m2, q_m1 = q_m1, q

    # Largest convergent index whose denominator is <= max_den.
    i = 0
    for idx, q in enumerate(cq):
        if q <= max_den:
            i = idx
        else:
            break

    p_i = cp[i]
    q_i = cq[i]

    prev_p = cp[i - 1] if i > 0 else 1
    prev_q = cq[i - 1] if i > 0 else 0

    # Generate the needed candidates.
    candidates = [(p_i, q_i)]
    if i > 0:
        candidates.append((cp[i - 1], cq[i - 1]))

    a_next = cf[i + 1]
    m_max = (max_den - prev_q) // q_i

    lo = max(1, m_max - 2)
    hi = min(a_next - 1, m_max + 2)

    for m in range(lo, hi + 1):
        p = m * p_i + prev_p
        q = m * q_i + prev_q
        if 1 <= q <= max_den:
            candidates.append((p, q))

    def valid_side(p: int, q: int) -> bool:
        if side == -1:
            return p * d <= n * q
        if side == 1:
            return p * d >= n * q
        return True

    def better(a_p: int, a_q: int, b_p: int, b_q: int) -> bool:
        if not valid_side(a_p, a_q):
            return False

        if side == -1:
            # Choose the larger value.
            return a_p * b_q > b_p * a_q

        if side == 1:
            # Choose the smaller value.
            return a_p * b_q < b_p * a_q

        # side == 0: choose the closest, then smaller q, then smaller p.
        ea = abs(n * a_q - d * a_p)
        eb = abs(n * b_q - d * b_p)

        left = ea * b_q
        right = eb * a_q

        if left != right:
            return left < right
        if a_q != b_q:
            return a_q < b_q
        return a_p < b_p

    best_p = 0
    best_q = 1

    # A valid fallback is usually one of the candidates, but keep the loop robust.
    first = True
    for p, q in candidates:
        p, q = reduce_frac(p, q)
        if q < 1:
            continue
        if first:
            if valid_side(p, q):
                best_p, best_q = p, q
                first = False
        else:
            if better(p, q, best_p, best_q):
                best_p, best_q = p, q

    if first:
        # Should not happen for valid input, but construct a fallback.
        if side == -1:
            p = n // d
            q = 1
            while p * d > n * q:
                p -= 1
        elif side == 1:
            p = -((-n) // d)
            q = 1
            while p * d < n * q:
                p += 1
        else:
            p = n // d
            q = 1

        best_p, best_q = reduce_frac(p, q)

    return (best_p, best_q)
